async function loadRealData(){try{const [mr,hr]=await Promise.all([fetch(`${API_BASE}/meta`),fetch(`${API_BASE}/historical/all`)]);if(!mr.ok||!hr.ok)throw new Error(`ANI data service request failed (${mr.status||hr.status}).`);apiMeta=await mr.json();const payload=await hr.json();provinceRegion=payload.province_regions||apiMeta.province_regions||{};data=payload.records||[]}catch(error){console.error('ANI data service request failed:',error);throw error}}

