let infoTipCounter=0;
function infoLabel(label){const tip=INFO_TIPS[label];if(!tip)return label;const id=`ani-tip-${++infoTipCounter}`,parts=String(label).trim().split(/\s+/),last=parts.pop()||'',prefix=parts.join(' ');return `<span class="infoLabelText">${prefix?`${prefix} `:''}<span class="infoLabelTail">${last}<span class="infoTip"><button type="button" class="infoTipTrigger" aria-label="Explain ${label}" aria-describedby="${id}" aria-expanded="false">i</button><span id="${id}" class="infoTipPopup" role="tooltip">${tip}</span></span></span></span>`}
const card=(x,c='')=>`<section class="card ${c}">${x}</section>`, title=(i,t,s='')=>`<div class="sectionTitle">${icon(i)}<div><h2>${t}</h2>${s?`<p>${s}</p>`:''}</div></div>`,stat=(i,l,v,s,t='green')=>card(`${icon(i)}<div><span>${infoLabel(l)}</span><strong>${v}</strong><small>${s}</small></div>`,`stat ${t}`),summary=rows=>`<div class="summary">${rows.map(([a,b])=>{const value=String(b).trim(),nowrap=/(?:MT\/ha|%|°C|mm|AM|PM)(?:\s*)$/.test(value)||/^\d+(?:\.\d+)?$/.test(value);return `<div><span>${infoLabel(a)}</span><strong class="${nowrap?'nowrapMetric':''}">${b}</strong></div>`}).join('')}</div>`;
function historicalYieldChart(rows){
  const sorted=[...rows].filter(r=>r.yield!=null&&Number.isFinite(Number(r.yield))).sort((a,b)=>a.year-b.year||a.quarter-b.quarter).slice(-20);
  if(!sorted.length)return '<div class="empty">No chart data are available for this selection.</div>';
  const vals=sorted.map(r=>Number(r.yield)),low=Math.min(...vals),high=Math.max(...vals),padding=Math.max((high-low)*.12,Math.abs(high)*.02,.05),min=low-padding,max=high+padding,range=max-min;
  const precision=Math.max(1,Math.min(8,Math.ceil(-Math.log10(range/4))+1));
  const render=(w,compact)=>{
    const h=290,left=68,right=24,top=24,bottom=48,pw=w-left-right,ph=h-top-bottom;
    const points=sorted.map((r,i)=>[left+(sorted.length===1?pw/2:i*pw/(sorted.length-1)),top+(max-vals[i])/range*ph]);
    // Reserve the last label first; require enough space for each full quarter/year label.
    const labels=[sorted.length-1],gap=compact?100:88;
    for(let i=sorted.length-2;i>=0;i--)if((i===0||i%4===0)&&points[labels.at(-1)][0]-points[i][0]>=gap)labels.push(i);
    labels.reverse();
    return `<svg class="chartSvg historicalYieldSvg ${compact?'compactYieldSvg':'wideYieldSvg'}" viewBox="0 0 ${w} ${h}" role="img" aria-label="Historical yield by quarter in metric tons per hectare, sorted chronologically"><title>Historical Yield Trend ? Yield (MT/ha)</title><desc>${sorted.length} quarterly observations, Q${sorted[0].quarter} ${sorted[0].year} through Q${sorted.at(-1).quarter} ${sorted.at(-1).year}. The vertical scale follows the displayed yield range.</desc>${Array.from({length:5},(_,i)=>{const y=top+i*ph/4;return `<line class="grid" x1="${left}" y1="${y}" x2="${w-right}" y2="${y}"/><text class="yieldTick" x="${left-9}" y="${y}" dy=".35em" text-anchor="end">${(max-i*range/4).toFixed(precision)}</text>`}).join('')}<line class="yieldAxis" x1="${left}" y1="${top}" x2="${left}" y2="${h-bottom}"/><text class="yieldAxisTitle" transform="translate(16 ${top+ph/2}) rotate(-90)" text-anchor="middle">Yield (MT/ha)</text><path class="line" d="${points.map((q,i)=>(i?'L':'M')+q.join(',')).join(' ')}"/>${points.map((q,i)=>`<circle cx="${q[0]}" cy="${q[1]}" r="3"><title>Q${sorted[i].quarter} ${sorted[i].year} ? ${vals[i].toFixed(2)} MT/ha</title></circle>`).join('')}${labels.map(i=>`<text class="yieldQuarter" x="${points[i][0]}" y="${h-18}" text-anchor="${i===sorted.length-1?'end':i===0?'start':'middle'}">Q${sorted[i].quarter} ${sorted[i].year}</text>`).join('')}</svg>`;
  };
  return `<div class="historicalYieldChart">${render(640,false)}${render(360,true)}</div>`;
}
function lineChart(rows,key='yield'){const sorted=[...rows].filter(r=>r[key]!=null&&Number.isFinite(Number(r[key]))).sort((a,b)=>a.year-b.year||a.quarter-b.quarter).slice(-20),w=800,h=270,p=52,vals=sorted.map(r=>Number(r[key]));if(!vals.length)return '<div class="empty">No chart data are available for this selection.</div>';const mn=Math.min(...vals)-.2,mx=Math.max(...vals)+.2,den=mx-mn||1,pts=sorted.map((r,i)=>[p+i*(w-2*p)/Math.max(1,sorted.length-1),h-p-(Number(r[key])-mn)/den*(h-2*p)]),path=pts.map((q,i)=>(i?'L':'M')+q[0]+','+q[1]).join(' ');return `<svg class="chartSvg" role="img" aria-label="Historical ${key} by quarter, sorted chronologically" viewBox="0 0 ${w} ${h}"><title>Historical ${key} by quarter</title>${[0,1,2,3,4].map(j=>`<line class="grid" x1="${p}" y1="${p+j*(h-2*p)/4}" x2="${w-p}" y2="${p+j*(h-2*p)/4}"/>`).join('')}<path class="line" d="${path}"/>${pts.map((q,i)=>`<circle cx="${q[0]}" cy="${q[1]}" r="3"><title>Q${sorted[i].quarter} ${sorted[i].year}: ${fmt(vals[i])}</title></circle>`).join('')}<text x="${p}" y="${h-10}">Q${sorted[0].quarter} ${sorted[0].year}</text><text x="${w-p}" y="${h-10}" text-anchor="end">Q${sorted.at(-1).quarter} ${sorted.at(-1).year}</text></svg>`}
function bars(rows,key='yield',cls='bar'){const w=720,h=Math.max(190,rows.length*34+24),left=190,right=70,top=12,rowH=(h-top-16)/Math.max(rows.length,1),max=Math.max(1,...rows.map(r=>Number(r[key])||0));return `<svg class="chartSvg horizontalBars" role="img" aria-label="${key} by province" viewBox="0 0 ${w} ${h}"><title>${key} by province</title>${rows.map((r,i)=>{const y=top+i*rowH,bw=Math.max(0,(Number(r[key])||0)/max*(w-left-right));return `<text x="${left-8}" y="${y+rowH*.67}" text-anchor="end">${r.province}</text><rect class="${cls}" x="${left}" y="${y+rowH*.2}" width="${bw}" height="${rowH*.58}" rx="4"/><text x="${left+bw+6}" y="${y+rowH*.67}">${fmt(r[key])}</text>`}).join('')}</svg>`}
function dashboard(){const recent=saved().slice(0,4),latestResult=recent[0]||null,trendSelection=latestResult&&data.some(r=>r.province===latestResult.province&&r.ecosystem===latestResult.ecosystem)?{province:latestResult.province,ecosystem:latestResult.ecosystem}:{province:'Nueva Ecija',ecosystem:'Irrigated'},rows=data.filter(r=>r.province===trendSelection.province&&r.ecosystem===trendSelection.ecosystem).sort((a,b)=>a.year-b.year||a.quarter-b.quarter),latestYear=data.reduce((m,r)=>Math.max(m,Number(r.year)),0),comp=Object.keys(provinceRegion).map(province=>{const v=data.filter(r=>r.province===province&&Number(r.year)===latestYear&&r.ecosystem==='Irrigated').map(r=>r.yield==null?NaN:Number(r.yield)).filter(Number.isFinite);return {province,yield:v.length?avg(v):NaN}}).filter(r=>Number.isFinite(r.yield)).sort((a,b)=>b.yield-a.yield).slice(0,8);return hero('DATA-DRIVEN INSIGHTS FOR A FOOD-SECURE PHILIPPINES','ANI — Provincial Palay Yield Forecasting System','Machine learning-based insights to support palay production planning and evidence-based agricultural decision-making.',true)+`<div class="grid4">${stat('','Provinces Represented',Object.keys(provinceRegion).length,'Philippine provinces represented')}${stat('','Historical Records',data.length,'Quarterly observations','gold')}${stat('','Data Coverage',historyCoverage(),apiMeta?.latest_agricultural_period?.status==='Preliminary'?'Latest integrated quarter is preliminary':'Processed ANI history','blue')}${stat('','Latest Model Result',recent[0]?recent[0].predictedYield+' MT/ha':'—',recent[0]?resultTypeFor(recent[0]):'No saved model results')}</div><div class="twoCol">${card(title('','Historical Yield Trend',`${trendSelection.province} · ${trendSelection.ecosystem}`)+`<div class="chart">${historicalYieldChart(rows)}</div>`)}${card(title('','Provincial Irrigated Yield Snapshot — '+(latestYear||'Unavailable'),apiMeta?.latest_agricultural_period?`Mean quarterly irrigated yield using integrated records through Q${apiMeta.latest_agricultural_period.quarter} ${apiMeta.latest_agricultural_period.year}.`:'Highest mean quarterly yields among provinces with integrated records for the year.')+`<div class="chart">${comp.length?bars(comp,'yield'):'<div class="empty">No irrigated yield records are available for the latest integrated year.</div>'}</div>`)}</div><div class="twoCol lower">${card(title('','Recent Model Results','Most recently generated model estimates.')+(recent.length?`<table class="compact"><thead><tr><th scope="col">Province</th><th scope="col">Ecosystem</th><th scope="col">Period</th><th scope="col">Yield</th><th scope="col">Result Type</th></tr></thead><tbody>${recent.map(f=>`<tr><td>${f.province}</td><td>${f.ecosystem}</td><td>Q${f.targetQuarter} ${f.targetYear}</td><td><b>${f.predictedYield} MT/ha</b></td><td>${resultTypeFor(f)}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">No model results saved yet.</div>'))}${card(`<div class="cta"><h2>Generate Palay Yield Estimate</h2><p>Select a province and target period to generate a model-based yield estimate.</p><button data-page="forecast" class="primaryBtn">Generate Estimate</button></div>`,'field-cta')}</div>${card(title('','How ANI Works','From historical agricultural data to a provincial palay-yield estimate.')+`<div class="flow"><div class="flowBox"><strong>Historical Agricultural Data</strong><small>Palay yield, production and area.</small></div><b>+</b><div class="flowBox"><strong>Agroclimatic Data</strong><small>Rainfall, temperature, relative humidity and wind speed.</small></div><b>&rarr;</b><div class="flowBox"><strong>Machine Learning</strong><small>Preprocessing, features and regression.</small></div><b>&rarr;</b><div class="flowBox"><strong>Provincial Yield Estimate</strong><small>Quarterly output in MT/ha.</small></div></div>`)}`}
function forecastPage(){const r=state.request,rel=data.filter(x=>x.province===r.province&&x.ecosystem===r.ecosystem).length,targets=state.availableTargets,years=[...new Set(targets.map(t=>t.year))],quarters=targets.filter(t=>t.year===r.targetYear),selected=quarters.find(t=>t.quarter===r.targetQuarter),disabled=state.availabilityLoading||!!state.availabilityError||!selected,assessment=state.nearestTargetAssessment,latest=apiMeta?.latest_agricultural_period,coverage=latest?`Integrated agricultural history: through Q${latest.quarter} ${latest.year}.${latest.status==='Preliminary'?' Q'+latest.quarter+' '+latest.year+' source values are preliminary and may be revised.':''}`:'Integrated agricultural history period is unavailable.',availabilityText=state.availabilityLoading?'Checking estimate availability…':state.availabilityError?state.availabilityError:targets.length?'Available periods meet historical and weather input requirements.':'No yield estimate is currently available for this selection.',yearOptions=years.length?years.map(y=>`<option value="${y}" ${r.targetYear===y?'selected':''}>${y}</option>`).join(''):'<option value="">No eligible year</option>',quarterOptions=quarters.length?quarters.map(t=>`<option value="${t.quarter}" ${r.targetQuarter===t.quarter?'selected':''}>Quarter ${t.quarter} — ${t.resultType}</option>`).join(''):'<option value="">No eligible quarter</option>',selectedMessage=selected?.temporalStatus==='RETROSPECTIVE_ESTIMATE'?'This target quarter has already ended. The model result uses pre-target historical inputs.':selected?.temporalStatus==='CURRENT_QUARTER_ESTIMATE'?'This is a current-quarter estimate; the target quarter is already in progress.':'This is a prospective forecast for a future target quarter.';return hero('GENERATE DATA-DRIVEN INSIGHTS','Generate Palay Yield Estimate','Select a province, ecosystem, and eligible target period. ANI classifies the result as prospective, current-quarter, or retrospective.')+`<div class="infoBox" role="note">${coverage}</div><div class="forecastGrid">${card('<div class="sectionTitle estimateConfigTitle"><div><h2>Estimate Settings</h2><p>Available periods have the historical and weather data needed to generate an estimate.</p></div></div>'+`<label class="formRow"><span>Province *</span><select id="province">${sortedProvinceNames().map(p=>`<option ${p===r.province?'selected':''}>${p}</option>`).join('')}</select></label><label class="formRow"><span>Region</span><input value="${provinceRegion[r.province]||''}" readonly tabindex="-1" aria-readonly="true" aria-label="Region for selected province"></label><label class="formRow"><span>Palay Ecosystem *</span><select id="ecosystem"><option ${r.ecosystem==='Irrigated'?'selected':''}>Irrigated</option><option ${r.ecosystem==='Rainfed'?'selected':''}>Rainfed</option></select></label><div class="formPair"><label class="formRow"><span>Target Year *</span><select id="targetYear" ${disabled?'disabled':''}>${yearOptions}</select></label><label class="formRow"><span>Target Quarter *</span><select id="targetQuarter" ${disabled||!quarters.length?'disabled':''}>${quarterOptions}</select></label></div><div class="infoBox" role="status">${availabilityText}</div>${selected?`<div class="infoBox temporalNotice" role="note"><strong>${selected.resultType}</strong><br>${selectedMessage}</div>`:''}${!targets.length&&!state.availabilityLoading&&!state.availabilityError?`<div class="infoBox"><strong>Yield estimate:</strong> Unavailable — historical/model input requirements are not satisfied.${assessment?.reason?`<p>${assessment.reason}</p>`:''}</div>`:''}${state.availabilityError?'<button type="button" id="retryAvailability" class="secondaryBtn">Retry availability check</button>':''}${state.forecastError?`<div class="inlineError" role="alert">${state.forecastError}</div>`:''}<div class="actions"><button id="generate" class="primaryBtn" ${disabled?'disabled':''}>Generate Estimate</button><button id="reset" class="secondaryBtn">Reset</button></div>`)}<div class="stack">${card(title('','Selected Estimate Context')+summary([['Province',r.province],['Region',provinceRegion[r.province]||'Unavailable'],['Ecosystem',r.ecosystem],['Target Period',selected?`Q${r.targetQuarter} ${r.targetYear}`:'No eligible period'],['Result Type',selected?.resultType||'Unavailable']]))}${card(title('','Available Historical Records')+`<div class="bigNumber">${rel}<small>historical records available</small></div>`,'bluePanel')}${card(title('','Yield Model')+`<h3>${apiMeta?.model?.model_name||'ANI XGBoost Regression'}</h3><p>The deployed model uses historical agricultural and lagged agroclimatic features. ANI presents historical benchmarks, satellite vegetation, official agri-weather, PAGASA climate-risk context, and market context separately so these supporting layers do not alter the XGBoost yield estimate. A supplementary water-balance analysis is shown only when a current matching outlook is available.</p>`,'goldPanel')}</div></div>`+environmentalDecisionSupport({province:r.province,ecosystem:r.ecosystem,yieldUnavailable:!targets.length})}
function processing(){const req=state.request,rows=data.filter(r=>r.province===req.province&&r.ecosystem===req.ecosystem),steps=[`Loading historical records for ${req.province}`,`Reviewing ${req.ecosystem.toLowerCase()} yield observations`,`Preparing Q${req.targetQuarter} seasonal features for ${req.targetYear}`,'Calculating historical and recent yield context','Applying the deployed model to produce a yield estimate','Saving result to Result History'];return hero('MODEL RESULT IN PROGRESS','Generating Yield Estimate','ANI is applying its deployed XGBoost model to the selected eligible target period.')+card(summary([['Province',req.province],['Region',provinceRegion[req.province]],['Ecosystem',req.ecosystem],['Target Period',`Q${req.targetQuarter} ${req.targetYear}`],['Historical Records Available',rows.length]])+`<div class="stepper">${steps.map((s,i)=>{const n=i+1,st=n<state.processingStep?'done':n===state.processingStep?'active':'pending';return `<div class="step ${st}"><span class="stepDot">${st==='done'?'✓':n}</span><div><strong>${n}. ${s}</strong><small>${st==='done'?'Completed':st==='active'?'In progress':'Waiting'}</small></div></div>`}).join('')}</div><div class="progress"><div style="width:${Math.min(100,state.processingStep/steps.length*100)}%"></div></div><div class="infoBox">The deployed XGBoost model uses pre-target historical inputs. Results are analytical estimates and are not official PSA crop statistics.</div>`) }
function resultWeatherValue(numeric,legacy,unit){if(typeof numeric==='number'&&Number.isFinite(numeric))return `${numeric.toFixed(1)} ${unit}`;return String(legacy??'Unavailable').replace(/\s+previous-quarter (?:rainfall|mean temperature)$/i,'')}
function satelliteVegetationContext(f){const s=f?.satelliteVegetationContext;if(!s)return '';const heading=title('◉','Satellite Vegetation Context','Pre-target MODIS cropland vegetation indicators shown separately from the yield model.');if(!s.available){return card(heading+`<div class="infoBox" role="note"><strong>Context unavailable:</strong> ${s.reason||'No usable pre-target satellite observation is available.'}<br><span class="muted">The yield estimate is unaffected because satellite vegetation is not an active XGBoost input.</span></div>`)}const ndvi=Number(s.croplandNdvi),evi=Number(s.croplandEvi),ndviDiff=Number(s.ndviPercentDifferenceFromMedian),eviDiff=Number(s.eviPercentDifferenceFromMedian),signed=v=>Number.isFinite(v)?`${v>0?'+':''}${v.toFixed(1)}%`:'Unavailable';const rows=[['Pre-Target Satellite Period',s.referencePeriod||`Q${s.referenceQuarter} ${s.referenceYear}`],['Cropland NDVI',Number.isFinite(ndvi)?ndvi.toFixed(3):'Unavailable'],['Cropland EVI',Number.isFinite(evi)?evi.toFixed(3):'Unavailable']];if(s.comparisonAvailable){rows.push(['Vegetation Status',s.vegetationStatus||'Unavailable'],['NDVI Seasonal Median',Number(s.ndviHistoricalMedian).toFixed(3)],['NDVI vs Seasonal Median',signed(ndviDiff)],['EVI Seasonal Median',Number(s.eviHistoricalMedian).toFixed(3)],['EVI vs Seasonal Median',signed(eviDiff)],['Earlier Same-Quarter Observations',s.historicalSameQuarterObservations??'Unavailable'])}else{rows.push(['Seasonal Comparison','Unavailable'],['Earlier Same-Quarter Observations',s.historicalSameQuarterObservations??'Unavailable'])}return card(heading+summary(rows)+(!s.comparisonAvailable&&s.reason?`<div class="infoBox" role="note">${s.reason}</div>`:'')+`<div class="infoBox" role="note"><strong>Supporting context only:</strong> These province-level MODIS indicators do not alter the XGBoost yield estimate or its eligibility.</div>`)}

function contextNumber(v,d=1,suffix=''){return v!==null&&v!==undefined&&Number.isFinite(Number(v))?`${Number(v).toFixed(d)}${suffix}`:'Unavailable'}
function signedContextPct(v){return v!==null&&v!==undefined&&Number.isFinite(Number(v))?`${Number(v)>0?'+':''}${Number(v).toFixed(1)}%`:'Unavailable'}
function historicalBenchmarkPanel(f){const b=f?.historicalBenchmarkContext;if(!b)return '';return card(title('▤','Historical Yield Benchmarks','Pre-target PSA history used to show typical and historically high same-season performance.')+summary([['Province Same-Quarter Median',contextNumber(b.provinceSameQuarterMedian,3,' MT/ha')],['Recent 5-Year Same-Quarter Median',contextNumber(b.provinceRecentFiveYearSameQuarterMedian,3,' MT/ha')],['Historical High-Yield Benchmark (75th Percentile)',contextNumber(b.attainableHistoricalBenchmark??b.provinceUpperQuartileBenchmark,3,' MT/ha')],['Gap vs Historical High-Yield Benchmark',signedContextPct(b.gapFromAttainableBenchmarkPct)],['Regional Same-Quarter Median',contextNumber(b.regionalSameQuarterMedian,3,' MT/ha')],['Estimate vs Regional Median',signedContextPct(b.differenceFromRegionalMedianPct)],['Historical Percentile',b.historicalPercentile!=null?`${Number(b.historicalPercentile).toFixed(1)}th percentile`:'Unavailable']])+`<div class="infoBox" role="note"><strong>Benchmark interpretation:</strong> The 75th-percentile benchmark represents historically high same-quarter performance for this province and ecosystem. It is a historical reference, not an agronomic optimum, potential yield, or guaranteed farm target.</div>`)}
function associatedSignalsPanel(f){const a=f?.associatedSignalsContext;if(!a)return '';const rain=a.rainfall||{},temp=a.temperature||{},ndvi=a.satelliteNdviDifferenceFromSeasonalMedianPct;return card(title('↕','Possible Contributing Signals',`Conditions observed before Q${f.targetQuarter} ${f.targetYear} that may help explain unusual yield patterns.`)+summary([['Reference Period',a.referencePeriod||'Unavailable'],['Same-Quarter Production Change',signedContextPct(a.sameQuarterProductionChangePct)],['Same-Quarter Harvested Area Change',signedContextPct(a.sameQuarterHarvestedAreaChangePct)],['Rainfall vs Seasonal Median',signedContextPct(rain.differenceFromSeasonalMedianPct)],['Previous-Quarter Rainfall',rain.valueMm!=null?`${Number(rain.valueMm).toFixed(1)} mm`:'Unavailable'],['Temperature vs Seasonal Median',temp.differenceFromSeasonalMedianC!=null?`${Number(temp.differenceFromSeasonalMedianC)>0?'+':''}${Number(temp.differenceFromSeasonalMedianC).toFixed(1)} °C`:'Unavailable'],['NDVI vs Seasonal Median',signedContextPct(ndvi)]])+`<div class="infoBox" role="note"><strong>Important:</strong> ${a.interpretationGuardrail||'These signals provide context and do not establish causation.'} Production and harvested-area changes are descriptive system changes, not independent agronomic causes of yield.</div>`)}
function vegetationRelationshipPanel(f){const r=f?.vegetationYieldRelationship;if(!r)return '';const heading=title('◉','Exploratory Vegetation–Yield Relationship','Historical association analysis shown separately from both the deployed model and the satellite-status summary.');if(!r.available)return card(heading+`<div class="infoBox" role="note"><strong>Relationship analysis unavailable:</strong> ${r.reason||'Not enough matched historical data are available.'}</div>`,'vegetationRelationshipCard');const corr=v=>v!=null&&Number.isFinite(Number(v))?Number(v).toFixed(3):'Unavailable';return card(heading+`<p class="muted relationshipIntro">Analysis for ${f.province} (${f.ecosystem}). Values are seasonally adjusted to reduce ordinary quarter-to-quarter seasonal differences.</p>`+summary([['Matched Historical Observations',r.matchedObservations??'Unavailable'],['Seasonally Adjusted NDVI–Yield Correlation',corr(r.ndviSeasonallyAdjustedCorrelation)],['NDVI Relationship',r.ndviInterpretation||'Unavailable'],['Seasonally Adjusted EVI–Yield Correlation',corr(r.eviSeasonallyAdjustedCorrelation)],['EVI Relationship',r.eviInterpretation||'Unavailable']])+`<div class="infoBox" role="note"><strong>Exploratory only:</strong> ${r.guardrail||'Correlation describes association and does not establish causation.'} This analysis does not alter the XGBoost estimate.</div>`,'vegetationRelationshipCard')}
function yieldPatternPanel(f){const p=f?.yieldPatternContext;if(!p)return '';const heading=title('↗','Yield Patterns & Trends','Historical same-season trends, seasonality, and unusual-position screening.');if(!p.available)return card(heading+'<div class="infoBox" role="note">Insufficient same-quarter history is available for pattern analysis.</div>');const trend=p.longTermSameQuarterTrendPctPerYear!=null?`${Number(p.longTermSameQuarterTrendPctPerYear)>0?'+':''}${Number(p.longTermSameQuarterTrendPctPerYear).toFixed(2)}% per year`:'Unavailable',recent=signedContextPct(p.recentThreeVsPreviousThreePct),rank=p.seasonalQuarterRank!=null?`${p.seasonalQuarterRank} of ${p.seasonalQuarterCount} quarters by historical median`:'Unavailable';return card(heading+summary([['Long-Term Same-Quarter Trend',trend],['Trend Direction',p.longTermTrendDirection||'Unavailable'],['Recent 3 vs Previous 3 Same-Quarter Median',recent],['Historical Position',p.anomalyStatus||'Unavailable'],['Historical Percentile',p.historicalPercentile!=null?`${Number(p.historicalPercentile).toFixed(1)}th percentile`:'Unavailable'],['Seasonal Quarter Rank',rank]])+`<div class="infoBox" role="note"><strong>Pattern interpretation:</strong> ${p.interpretation||'Historical patterns describe past behavior and do not establish causation.'}</div>`)}
function farmerGuidancePanel(f){const g=f?.farmerGuidanceContext;if(!g?.available)return '';const items=(g.items||[]).map(item=>`<article class="guidanceItem"><h3>${item.title}</h3><p>${item.detail}</p><small>Basis: ${item.basis}</small></article>`).join('');return card(title('✓','What to Monitor Next','Transparent planning prompts based on ANI context and official information; not a prescription.')+`<div class="guidanceGrid">${items}</div><div class="infoBox" role="note"><strong>Guidance guardrail:</strong> ${g.guardrail||'Verify conditions locally before acting.'}</div>`,'guidanceCard')}
function marketContextPanel(f){const m=f?.marketContext;if(!m)return '';const heading=title('₱','Provincial Palay Market Context','Latest available PSA farmgate-price information; separate from the yield model.');if(!m.available)return card(heading+`<div class="infoBox" role="note">${m.reason||'Market context is unavailable for this province.'}</div>`);return card(heading+summary([['Market Reference Period',m.period||'Unavailable'],['Data Availability',m.dataFreshness||'Unavailable'],['Farmgate Price',m.pricePhpPerKg!=null?`₱${Number(m.pricePhpPerKg).toFixed(2)}/kg`:'Unavailable'],['Month-over-Month Change',signedContextPct(m.monthOverMonthChangePct)],['Year-over-Year Change',signedContextPct(m.yearOverYearChangePct)],['Trailing 12-Month Range',m.trailing12MonthMinPhpPerKg!=null&&m.trailing12MonthMaxPhpPerKg!=null?`₱${Number(m.trailing12MonthMinPhpPerKg).toFixed(2)}–₱${Number(m.trailing12MonthMaxPhpPerKg).toFixed(2)}/kg`:'Unavailable']])+`<p class="muted">${m.definition||''}</p><div class="infoBox" role="note"><strong>Market context only:</strong> Farmgate prices do not alter the XGBoost yield estimate. ${m.dataFreshness==='Earlier Available Provincial Record'&&m.latestIntegratedPeriod?`The latest integrated PSA matrix reaches ${m.latestIntegratedPeriod}, but this province's latest reported value is ${m.period}. `:''}${m.note||''}</div><p><a href="${m.sourceUrl}" target="_blank" rel="noopener noreferrer">View PSA OpenSTAT source</a></p>`)}
function officialAgriWeatherPanel(f){const w=f?.officialAgriWeatherContext;if(!w)return '';const heading=title('☁','Official PAGASA Agri-Weather Context','Latest integrated regional agri-weather information; separate from the target-period model inputs.');if(!w.available)return card(heading+`<div class="infoBox" role="note">${w.reason||'Official agri-weather context is unavailable.'}</div>`);const stages=(w.riceStages||[]).join(', ')||'Not specified',ops=(w.farmOperations||[]).join(', ')||'Not specified';return card(heading+summary([['Forecast Period',w.forecastPeriod||'Unavailable'],['PAGASA Region',w.regionLabel||'Unavailable'],['Forecast Rainfall',w.forecastRainfallMm?`${w.forecastRainfallMm} mm`:'Unavailable'],['Rainy Days (>1 mm)',w.rainyDaysGt1Mm||'Unavailable'],['Temperature',w.temperatureC?`${w.temperatureC} °C`:'Unavailable'],['Relative Humidity',w.relativeHumidityPct?`${w.relativeHumidityPct}%`:'Unavailable'],['Rice Stages in Regional Outlook',stages],['Farm Operations in Regional Outlook',ops]])+`<div class="infoBox" role="note"><strong>Official context:</strong> This PAGASA information supports current farm planning but does not change the ANI XGBoost yield estimate.</div><p><a href="${w.sourceUrl}" target="_blank" rel="noopener noreferrer">View PAGASA 10-Day Regional Agri-Weather Information</a></p>`)}
function officialClimateRiskPanel(f){const c=f?.officialClimateRiskContext;if(!c)return '';const heading=title('','Official PAGASA Climate Risk Context','Published ENSO and provincial drought information; separate from the ANI yield model.');if(!c.available)return card(heading+`<div class="infoBox" role="note">${c.reason||'Official climate-risk context is unavailable for this province.'}</div>`);const enso=c.ensoAdvisory||{},assessment=c.droughtAssessment||{},outlook=(c.droughtOutlook||[]).slice(0,6),monthLabel=value=>{if(!value)return 'Unavailable';const parts=String(value).split('-'),d=new Date(Number(parts[0]),Number(parts[1])-1,1);return d.toLocaleString('en-US',{month:'long',year:'numeric'})},ensoTitle=String(enso.title||'Unavailable').replace('El Nino','El Niño').replace('La Nina','La Niña'),outlookText=outlook.length?outlook.map(x=>`${monthLabel(x.date)}: ${x.status}`).join(' · '):'Unavailable';return card(heading+summary([['ENSO Advisory',ensoTitle],['ENSO Issue Date',enso.issuedDate||'Unavailable'],['Latest Drought Assessment',assessment.date?`${monthLabel(assessment.date)} — ${assessment.status}`:'Unavailable'],['Drought Outlook',outlookText]])+`<div class="infoBox" role="note"><strong>Official climate context:</strong> ANI displays PAGASA's published drought classifications and ENSO advisory. It does not calculate its own drought category, and this information does not alter the XGBoost yield estimate.</div><p><a href="${c.droughtSourceUrl}" target="_blank" rel="noopener noreferrer">View PAGASA Drought Monitor</a> · <a href="${c.ensoSourceUrl}" target="_blank" rel="noopener noreferrer">View PAGASA ENSO Advisories</a></p>`)}
function contextPanelGrid(...panels){const visible=panels.filter(Boolean);return visible.length?`<div class="contextGrid">${visible.join('')}</div>`:''}
function currentFarmerContext(f){return contextPanelGrid(marketContextPanel(f),officialAgriWeatherPanel(f),officialClimateRiskPanel(f))}

function resultChart(rows,result){const historical=[...rows].filter(r=>((Number(r.year)<Number(result.targetYear))||(Number(r.year)===Number(result.targetYear)&&Number(r.quarter)<Number(result.targetQuarter)))&&r.yield!=null&&Number.isFinite(Number(r.yield))).sort((a,b)=>a.year-b.year||a.quarter-b.quarter).slice(-20),target=Number(result.predictedYield),w=920,h=430,left=78,right=36,top=32,bottom=100,all=[...historical.map(r=>Number(r.yield)),target],low=Math.min(...all),high=Math.max(...all),pad=Math.max(.15,(high-low)*.12),mn=low-pad,mx=high+pad,den=mx-mn||1,plotW=w-left-right,plotH=h-top-bottom,slot=plotW/(historical.length+1),pts=historical.map((r,i)=>[left+i*slot+slot/2,top+(mx-Number(r.yield))/den*plotH]),tx=left+historical.length*slot+slot/2,ty=top+(mx-target)/den*plotH,path=pts.map((q,i)=>(i?'L':'M')+q[0]+','+q[1]).join(' ');return `<svg class="chartSvg resultChartSvg" role="img" aria-label="Historical yields followed by a distinct model estimate for Q${result.targetQuarter} ${result.targetYear}" viewBox="0 0 ${w} ${h}"><title>Historical yields and Q${result.targetQuarter} ${result.targetYear} model estimate</title>${[0,1,2,3,4].map(j=>`<line class="grid" x1="${left}" y1="${top+j*plotH/4}" x2="${w-right}" y2="${top+j*plotH/4}"/>`).join('')}<text class="resultAxisTitle" transform="translate(18 ${top+plotH/2}) rotate(-90)" text-anchor="middle">Yield (MT/ha)</text>${[0,1,2,3,4].map(j=>`<text class="resultAxisTick" x="${left-10}" y="${top+j*plotH/4}" text-anchor="end" dominant-baseline="middle">${(mx-j*den/4).toFixed(2)}</text>`).join('')}<path class="line" d="${path}"/>${pts.map((q,i)=>`<circle cx="${q[0]}" cy="${q[1]}" r="4"><title>Observed history: Q${historical[i].quarter} ${historical[i].year}, ${fmt(historical[i].yield)} MT/ha</title></circle>`).join('')}<path class="estimateConnector" d="M${pts.at(-1)?.[0]??left},${pts.at(-1)?.[1]??ty} L${tx},${ty}"/><path class="estimateStem" d="M${tx},${top} L${tx},${top+plotH}"/><circle class="estimateMarker" cx="${tx}" cy="${ty}" r="10"><title>Model estimate: Q${result.targetQuarter} ${result.targetYear}, ${fmt(target)} MT/ha</title></circle>${historical.map((r,i)=>i%4===0&&tx-pts[i][0]>=slot*2?`<text class="resultAxisTick" x="${pts[i][0]}" y="${top+plotH+26}" text-anchor="middle">Q${r.quarter} ${r.year}</text>`:'').join('')}<text class="resultAxisTick" x="${tx}" y="${top+plotH+26}" text-anchor="middle"><tspan x="${tx}">Q${result.targetQuarter} ${result.targetYear}</tspan><tspan x="${tx}" dy="18">Estimate</tspan></text><text class="resultXAxisTitle" x="${w/2}" y="${h-14}" text-anchor="middle">Quarter / Year</text></svg>`}

function resultSection(id,eyebrowText,heading,description,content){return `<section id="${id}" class="resultSection" aria-labelledby="${id}Title"><div class="resultSectionHeader"><span class="eyebrow">${eyebrowText}</span><h2 id="${id}Title">${heading}</h2><p>${description}</p></div>${content}</section>`}
function resultSectionNav(f){const retrospective=resultTypeFor(f)==='Retrospective Estimate';return retrospective
  ? `<nav class="resultSectionNav" aria-label="Result sections"><a href="#yield-estimate">Your Yield Estimate</a><a href="#comparison">How It Compares</a><a href="#conditions">Pre-Target Conditions</a><a href="#current-planning">Current Planning Context</a><a href="#technical-details">Technical Details</a></nav>`
  : `<nav class="resultSectionNav" aria-label="Result sections"><a href="#yield-estimate">Your Yield Estimate</a><a href="#comparison">How It Compares</a><a href="#conditions">Conditions to Watch</a><a href="#weather-climate">Weather & Climate</a><a href="#market-context">Market Context</a><a href="#technical-details">Technical Details</a></nav>`}
function resultTechnicalDetails(content){return `<details id="technical-details" class="resultTechnicalDetails"><summary><span><b>Technical Details</b><small>Model method and supplementary analysis</small></span><span aria-hidden="true">+</span></summary><div class="resultTechnicalBody">${content}</div></details>`}
function resultPage(){const f=state.current;if(!f)return card('<div class="empty">No current model result.</div>');const rows=data.filter(r=>r.province===f.province&&r.ecosystem===f.ecosystem),presentation=resultPresentation(f),resultType=resultTypeFor(f),isRetrospective=resultType==='Retrospective Estimate',diff=Number(f.percentDifferenceFromMedian??f.percentDifferenceFromAverage),differenceText=Number.isFinite(diff)?`${Math.abs(diff).toFixed(1)}% ${diff>0?'above':diff<0?'below':'equal to'}`:'unavailable relative to',statusMap={WITHIN_RANGE:'Within Typical Historical Range',BELOW_RANGE:'Below Typical Historical Range',ABOVE_RANGE:'Above Typical Historical Range'},status=statusMap[f.historicalStatus]||f.historicalStatus||'Unavailable',inputStatusNote=f.previousQuarterAgriculturalStatus==='Preliminary'?`<div class="infoBox" role="note"><strong>Input data status:</strong> This estimate uses preliminary PSA agricultural observations from the immediately preceding quarter. These source values may be revised in a later PSA release.</div>`:'';const interpretation=`ANI estimates ${f.predictedYield} MT/ha for Q${f.targetQuarter} ${f.targetYear}. This result is ${differenceText} the same-quarter historical median and is ${status.toLowerCase()}.`;const estimateLabel=isRetrospective?'Retrospective Model Estimate':presentation.metric,estimateNote=isRetrospective?'Reconstructed estimate for a completed quarter; not the official observed yield.':presentation.description;const yieldContent=`<div class="resultStats">${stat('',estimateLabel,f.predictedYield+' MT/ha',estimateNote)}${stat('','Same-Quarter Median',f.historicalMedian??f.historicalAverage,'MT/ha','blue')}${stat('','Same Quarter Last Year',f.previousComparableYield+' MT/ha','Historical comparison','gold')}${stat('','Difference from Median',(Number.isFinite(diff)&&diff>0?'+':'')+`${Number.isFinite(diff)?diff:'Unavailable'}%`,'Relative to same-quarter historical median')}${stat('','Typical Historical Range',`<span class="historicalRangeValue">${f.q25??f.historicalMin}-${f.q75??f.historicalMax} MT/ha</span>`,'25th-75th percentile','blue')}</div><div class="resultGrid">${card(title('','Historical vs Model Result',`${f.province} (${f.ecosystem}) for Q${f.targetQuarter} ${f.targetYear}.`)+`<div class="chart large">${resultChart(rows,f)}</div>`)}${card(title('','Model Result Context')+summary([['Result Type',resultType],['Recent 4-Quarter Yield Average',`${f.recentYieldAverage} MT/ha`],['Same-Quarter Median',`${f.historicalMedian??f.historicalAverage} MT/ha`],['Historical Status',status],['Same-Quarter Production Change',`${f.laggedProductionTrend>0?'+':''}${f.laggedProductionTrend}%`],['Same-Quarter Harvested Area Change',`${f.laggedAreaTrend>0?'+':''}${f.laggedAreaTrend}%`],['Previous-Quarter Rainfall',resultWeatherValue(f.previousQuarterRainfallMm,f.rainfallIndicator,'mm')],['Previous-Quarter Mean Temperature',resultWeatherValue(f.previousQuarterMeanTemperatureC,f.temperatureIndicator,'°C')],['Prior Historical Records',f.dataPointsUsed],['Generated At',new Date(f.generatedAt).toLocaleString()]]))}</div>${card(title('','Result Interpretation')+`<p>${interpretation}</p>`)}`;const compareContent=contextPanelGrid(historicalBenchmarkPanel(f),yieldPatternPanel(f));const conditionsContent=`${contextPanelGrid(associatedSignalsPanel(f),satelliteVegetationContext(f))}${vegetationRelationshipPanel(f)}`;const weatherContent=contextPanelGrid(officialAgriWeatherPanel(f),officialClimateRiskPanel(f));const marketContent=marketContextPanel(f);const currentPlanningNote=isRetrospective?`<div class="infoBox currentPlanningNotice" role="note"><strong>Current planning information:</strong> The information below reflects the latest integrated PAGASA and market context available now. It did not influence the retrospective Q${f.targetQuarter} ${f.targetYear} model estimate and should not be interpreted as explaining past yield conditions.</div>`:'';const currentPlanningContent=`${currentPlanningNote}${weatherContent}${farmerGuidancePanel(f)}${marketContent}`;const supplementary=environmentalDecisionSupport(f);const technicalContent=`${card(title('','How was this model result generated?')+`<p>ANI applies the deployed XGBoost model to pre-target historical agricultural and lagged agroclimatic inputs. Historical benchmarks, associated pre-target signals, satellite vegetation, PSA farmgate-price context, and official PAGASA agri-weather and climate-risk information are separate interpretive layers and do not alter the XGBoost estimate.</p>`)}${supplementary}`;return hero('MODEL RESULT - '+resultType.toUpperCase(),presentation.title,presentation.description)+(presentation.note?`<div class="infoBox temporalNotice">${presentation.note}</div>`:'')+inputStatusNote+resultSectionNav(f)+resultSection('yield-estimate','RESULT OVERVIEW','Your Yield Estimate',isRetrospective?'This is a reconstructed model estimate for a completed quarter, not the official observed yield.':'Start with ANI\'s model estimate and the most important historical context.',yieldContent)+resultSection('comparison','HISTORICAL CONTEXT','How It Compares','Compare the estimate with province and regional historical reference values.',compareContent)+resultSection('conditions','PRE-TARGET CONTEXT',isRetrospective?'Conditions Observed Before the Target Quarter':'Conditions to Watch',isRetrospective?'Review agricultural, weather, and vegetation signals observed before the completed target quarter. These signals provide context and do not establish causation.':'Review associated agricultural, weather, and vegetation signals observed before the target quarter.',conditionsContent)+(isRetrospective?resultSection('current-planning','CURRENT INFORMATION','Current Planning Context','Use the latest official weather, climate, and market information for present planning—not as an explanation of the completed target quarter.',currentPlanningContent):resultSection('weather-climate','OFFICIAL CONTEXT','Weather & Climate','Official PAGASA agri-weather, ENSO, and drought information for planning context.',weatherContent)+resultSection('market-context','MARKET CONTEXT','Palay Market Context','Latest integrated provincial farmgate-price information shown separately from yield prediction.',marketContent))+`<div class="actions wide"><button id="print" class="secondaryBtn">Print / Save as PDF</button><button data-page="forecast" class="secondaryBtn">Generate Another Estimate</button></div>`+resultTechnicalDetails(technicalContent)}

function historical(){const filtered=data.filter(r=>(state.filterProvince==='All Provinces'||r.province===state.filterProvince)&&(state.filterEco==='All Ecosystems'||r.ecosystem===state.filterEco)&&(state.filterYear==='All Years'||r.year==state.filterYear)&&r.province.toLowerCase().includes(state.query.toLowerCase())),pageSize=10,pageCount=Math.max(1,Math.ceil(filtered.length/pageSize));state.historicalPage=Math.min(state.historicalPage,pageCount-1);const pageStart=state.historicalPage*pageSize,shown=filtered.slice(pageStart,pageStart+pageSize),exactSelection=state.filterProvince!=='All Provinces'&&state.filterEco!=='All Ecosystems',chartRows=exactSelection?filtered.filter(r=>r.province===state.filterProvince&&r.ecosystem===state.filterEco).sort((a,b)=>a.year-b.year||a.quarter-b.quarter):[];const n=(v,d=2)=>v!=null&&Number.isFinite(Number(v))?Number(v).toLocaleString(undefined,{maximumFractionDigits:d}):'—';return hero('DATA-DRIVEN INSIGHTS FOR A FOOD-SECURE PHILIPPINES','Historical Agricultural Data','Explore integrated provincial agricultural history with associated weather and satellite vegetation summaries.')+(apiMeta?.latest_agricultural_period?`<div class="infoBox" role="note">Integrated agricultural history: through Q${apiMeta.latest_agricultural_period.quarter} ${apiMeta.latest_agricultural_period.year}.${apiMeta.latest_agricultural_period.status==='Preliminary'?' Q'+apiMeta.latest_agricultural_period.quarter+' '+apiMeta.latest_agricultural_period.year+' source values are preliminary and may be revised.':''}</div>`:'')+card(`<div class="filters"><select id="filterProvince" aria-label="Filter by province"><option>All Provinces</option>${sortedProvinceNames().map(p=>`<option ${state.filterProvince===p?'selected':''}>${p}</option>`).join('')}</select><select id="filterEco" aria-label="Filter by ecosystem"><option>All Ecosystems</option><option ${state.filterEco==='Irrigated'?'selected':''}>Irrigated</option><option ${state.filterEco==='Rainfed'?'selected':''}>Rainfed</option></select><select id="filterYear" aria-label="Filter by year"><option>All Years</option>${[...new Set(data.map(r=>r.year))].sort((a,b)=>a-b).map(y=>`<option ${state.filterYear==y?'selected':''}>${y}</option>`).join('')}</select><label class="search"><svg aria-hidden="true" viewBox="0 0 24 24"><circle cx="10.8" cy="10.8" r="6.8"/><path d="m16 16 5 5"/></svg><input id="query" aria-label="Search province" placeholder="Search province…" value="${state.query}"></label><button id="resetFilters" class="secondaryBtn">Reset Filters</button></div>`)+`${exactSelection?`<div class="threeCol">${card(title('→','Yield Over Time',`${state.filterProvince} · ${state.filterEco}`)+`<div class="chart small">${lineChart(chartRows)}</div>`)}${card(title('▤','Production Volume')+`<div class="chart small">${lineChart(chartRows,'productionVolume')}</div>`)}${card(title('☁','Rainfall Trend')+`<div class="chart small">${lineChart(chartRows,'rainfall')}</div>`)}</div><div class="twoCol">${card(title('◉','Cropland NDVI Trend','Province-level cropland vegetation index from MODIS.')+`<div class="chart small">${lineChart(chartRows,'croplandNdvi')}</div>`)}${card(title('◉','Cropland EVI Trend','Province-level enhanced vegetation index from MODIS.')+`<div class="chart small">${lineChart(chartRows,'croplandEvi')}</div>`)}</div><div class="infoBox" role="note"><strong>Satellite context:</strong> NDVI and EVI are province-level cropland summaries. They are available for analysis but are not inputs to the active deployed yield model.</div>`:card('<div class="empty">Select one province and one ecosystem to view historical trend charts.</div>')}`+card(`<div class="tableHeader">${title('▣','Historical Agricultural Data','Processed agricultural history with associated agroclimatic and satellite vegetation summaries.')}<span class="warning">Integrated data</span></div><div class="tableWrap"><table><thead><tr><th scope="col">Province</th><th scope="col">Region</th><th scope="col">Year</th><th scope="col">Quarter</th><th scope="col">Ecosystem</th><th scope="col">Production (MT)</th><th scope="col">Area Harvested (ha)</th><th scope="col">Yield (MT/ha)</th><th scope="col">Rainfall (mm)</th><th scope="col">Mean Temperature (°C)</th><th scope="col">Relative Humidity (%)</th><th scope="col">Cropland NDVI</th><th scope="col">Cropland EVI</th></tr></thead><tbody>${shown.map(r=>`<tr><td><b>${r.province}</b></td><td>${r.region}</td><td>${r.year}</td><td>Q${r.quarter}</td><td>${r.ecosystem}</td><td>${n(r.productionVolume)}</td><td>${n(r.areaHarvested)}</td><td>${n(r.yield)}</td><td>${n(r.rainfall)}</td><td>${n(r.avgTemperature)}</td><td>${n(r.relativeHumidity)}</td><td>${n(r.croplandNdvi,3)}</td><td>${n(r.croplandEvi,3)}</td></tr>`).join('')}</tbody></table></div><div class="pagination"><p class="muted">Showing ${filtered.length?`${pageStart+1}–${pageStart+shown.length}`:'0'} of ${filtered.length} matching records.</p><div class="paginationControls"><button id="firstPage" class="secondaryBtn" aria-label="Go to first page" title="First page" ${state.historicalPage===0?'disabled':''}>«</button><button id="previousPage" class="secondaryBtn" ${state.historicalPage===0?'disabled':''}>Previous</button><span>Page ${state.historicalPage+1} of ${pageCount}</span><button id="nextPage" class="secondaryBtn" ${state.historicalPage>=pageCount-1?'disabled':''}>Next</button><button id="lastPage" class="secondaryBtn" aria-label="Go to last page" title="Last page" ${state.historicalPage>=pageCount-1?'disabled':''}>»</button></div></div>`) }
function history(){const items=saved();return hero('DATA-DRIVEN INSIGHTS FOR A FOOD-SECURE PHILIPPINES','Result History','Saved model results retain the temporal type assigned when generated.')+`<div class="grid2">${stat('','Total Model Results',items.length,'Saved on this device')}${card('<button data-page="forecast" class="primaryBtn">Generate New Estimate</button>','ctaMini')}</div>`+card(items.length?`<div class="tableWrap"><table><thead><tr><th scope="col">Result ID</th><th scope="col">Province</th><th scope="col">Ecosystem</th><th scope="col">Target Period</th><th scope="col">Yield Estimate</th><th scope="col">Generated</th><th scope="col">Result Type</th><th scope="col">Model</th><th scope="col">Actions</th></tr></thead><tbody>${items.map(f=>`<tr><td>${f.forecastId}</td><td>${f.province}</td><td>${f.ecosystem}</td><td>Q${f.targetQuarter} ${f.targetYear}</td><td><b>${f.predictedYield} MT/ha</b></td><td>${new Date(f.generatedAt).toLocaleString()}</td><td>${resultTypeFor(f)}</td><td>${f.modelName||'ANI XGBoost'} ${f.modelVersion||''}</td><td><div class="rowActions"><button data-view="${f.forecastId}">View</button><button class="danger" data-delete="${f.forecastId}">Delete</button></div></td></tr>`).join('')}</tbody></table></div><div class="actions"><button id="clearAll" class="secondaryBtn dangerText">Clear All</button></div>`:'<div class="empty">No model results yet. Generate an estimate and it will appear here automatically.</div>')}
function model(){const m=apiMeta?.model||{},ev=m.evaluation||{},latest=apiMeta?.latest_agricultural_period,weather=apiMeta?.latest_weather_period,satellitePeriod=apiMeta?.latest_satellite_period,sat=apiMeta?.satellite_vegetation||{},satHoldout=sat.holdout_2025||{},satCurrent=satHoldout.current_feature_model||{},satCandidate=satHoldout.satellite_augmented_model||{},satCoverage=satHoldout.selected_feature_complete_case?.coverage_pct,trainPeriod=m.trained_through_year?`Q${m.trained_through_quarter??4} ${m.trained_through_year}`:'Unavailable',integratedPeriod=latest?`Q${latest.quarter} ${latest.year}`:'Unavailable',satelliteCoverage=satellitePeriod?`Q${satellitePeriod.quarter} ${satellitePeriod.year}`:'Unavailable',dataStatus=latest?.status==='Preliminary'?`<div class="infoBox" role="note"><strong>Integrated data status:</strong> Agricultural history extends through ${integratedPeriod}. The latest quarter is preliminary in the current PSA source release and may be revised.</div>`:'',satelliteDecision=sat.promote_to_deployment===false?`<div class="infoBox" role="note"><strong>Satellite feature assessment:</strong> ANI maintains cropland-masked MODIS NDVI/EVI data, but these variables are not inputs to the active deployed model. On the fixed 2025 holdout, the current feature model MAE was ${Number.isFinite(satCurrent.mae)?satCurrent.mae.toFixed(3):'n/a'} MT/ha and the selected satellite-augmented candidate MAE was ${Number.isFinite(satCandidate.mae)?satCandidate.mae.toFixed(3):'n/a'} MT/ha. Complete-case satellite coverage was ${Number.isFinite(satCoverage)?satCoverage.toFixed(1):'n/a'}%. The extraction mirror has a Q3 2025 source gap, which ANI leaves missing rather than interpolating. The agricultural-plus-weather feature set is retained because the satellite candidate did not satisfy the predefined promotion criteria.</div>`:'';return hero('DATA, MODELS, AND METHODS FOR A FOOD-SECURE PHILIPPINES','Model & Data','Explore ANI data sources, model methods, and chronological evaluation.',true)+`${card(title('▤','Model Evaluation Dataset','Fixed evaluation period: 2001–2025. Final holdout: 2025.')+`<div class="infoBox" role="note">Integrated agricultural history: ${integratedPeriod}. Deployment model training: through ${trainPeriod}. Reported performance metrics remain based on the fixed 2025 chronological holdout.</div>${dataStatus}`)}${card(title('◷','Data Freshness & Update Cadence','Latest integrated period by source. ANI should refresh each source according to its publication schedule rather than label all sources as real-time.')+`<div class="freshnessGrid"><div><span>Agricultural history</span><strong>${integratedPeriod}</strong><small>PSA · quarterly official release</small></div><div><span>Agroclimatic history</span><strong>${weather?`Q${weather.quarter} ${weather.year}`:'Unavailable'}</strong><small>NASA POWER · integrated for model-ready history</small></div><div><span>Satellite vegetation</span><strong>${satelliteCoverage}</strong><small>MODIS source · 16-day product, aggregated by quarter</small></div><div><span>Palay farmgate price</span><strong>${apiMeta?.latest_market_period?new Date(apiMeta.latest_market_period.year,apiMeta.latest_market_period.month-1,1).toLocaleString('en-US',{month:'long',year:'numeric'}):'Unavailable'}</strong><small>PSA · monthly provincial price context</small></div><div><span>PAGASA agri-weather</span><strong>${apiMeta?.official_agri_weather?.forecastPeriod||'Unavailable'}</strong><small>Official planning context · update when a new bulletin is integrated</small></div></div><div class="infoBox" role="note"><strong>Freshness rule:</strong> “Latest available” is used instead of “real-time” when the official source is periodic. Source periods remain separate from XGBoost training and evaluation dates.</div>`)}<div class="modelGrid">${stat('◉','Prediction Target','Provincial quarterly yield','Metric tons per hectare (MT/ha)')}${stat('◉','Deployment Model','XGBoost Regression','Active XGBoost regression model','gold')}${card(title('▤',infoLabel('Chronological Holdout Evaluation'),`Computed on ${ev.eligible_rows??'n/a'} eligible cases from the 2025 holdout.`)+`<div class="modelCards"><div><b>Seasonal Naive Baseline</b><span>Previous-year same-quarter yield</span><small>${infoLabel('MAE')} ${ev.baseline?.mae?.toFixed(3)??'n/a'} MT/ha</small><small>${infoLabel('RMSE')} ${ev.baseline?.rmse?.toFixed(3)??'n/a'} MT/ha</small><small>${infoLabel('R²')} ${ev.baseline?.r2?.toFixed(3)??'n/a'}</small></div><div class="selected"><b>XGBoost Regressor</b><span>Deployed model</span><small>${infoLabel('MAE')} ${ev.xgboost?.mae?.toFixed(3)??'n/a'} MT/ha</small><small>${infoLabel('RMSE')} ${ev.xgboost?.rmse?.toFixed(3)??'n/a'} MT/ha</small><small>${infoLabel('R²')} ${ev.xgboost?.r2?.toFixed(3)??'n/a'}</small></div></div>`)}</div><div class="twoCol">${card(title('–','Evaluation and Deployment Timeline','Chronological evaluation followed by deployment refit.')+`<div class="timeline"><div><b>Evaluation training window: records through 2024</b></div><div><b>Final chronological holdout: eligible 2025 cases</b></div><div><b>Deployment refit: eligible records through ${trainPeriod}</b></div></div><div class="infoBox">The selected pipeline is refit after the fixed 2025 holdout evaluation. Later integrated observations may support lagged inference without being included in model fitting.</div>`)}${card(title('◉','Model Provenance')+summary([['Model Version',m.model_version||'Unavailable'],['scikit-learn Version',m.scikit_learn_version||'Unavailable'],['Training Rows',m.training_rows??'Unavailable'],['Trained Through',trainPeriod],['Integrated History',integratedPeriod],['Weather Through',weather?`Q${weather.quarter} ${weather.year}`:'Unavailable'],['Satellite Layer Through',satelliteCoverage]]))}</div><div class="twoCol">${card(title('◉','Data Sources','What feeds the XGBoost model versus what ANI shows as supporting context.')+`<div class="sourceGrid"><div><div class="sourceHeading"><b>Agricultural Data</b><span class="sourceRole modelInput">Model input</span></div><p>Processed PSA OpenSTAT production and area-harvested records, with yield calculated as production divided by area harvested.</p></div><div><div class="sourceHeading"><b>Agroclimatic Data</b><span class="sourceRole modelInput">Model input</span></div><p>NASA POWER rainfall, temperature, relative humidity, and wind speed summarized by quarter.</p></div><div><div class="sourceHeading"><b>Satellite Vegetation Data</b><span class="sourceRole supporting">Supporting context</span></div><p>NASA MODIS/Terra MOD13A1 cropland-masked NDVI and EVI summaries aggregated to the province-quarter level.</p></div><div><div class="sourceHeading"><b>Palay Market Context</b><span class="sourceRole supporting">Supporting context</span></div><p>PSA OpenSTAT Farm Price Survey for Palay, summarized from monthly provincial farmgate prices.</p></div><div><div class="sourceHeading"><b>Official Agri-Weather Context</b><span class="sourceRole supporting">Supporting context</span></div><p>DOST-PAGASA 10-Day Regional Agri-Weather Information for the latest integrated regional rainfall, temperature, humidity, rice stages, and farm operations.</p></div><div><div class="sourceHeading"><b>Official Climate Risk Context</b><span class="sourceRole supporting">Supporting context</span></div><p>DOST-PAGASA ENSO advisories and provincial meteorological drought assessment/outlook are displayed as published official context.</p></div></div>`)}${card(title('♨','Active Feature Groups')+`<ul class="featureList"><li><b>Geographic:</b> Province, ecosystem</li><li><b>Temporal:</b> Target quarter</li><li><b>Historical yield:</b> Yield ${infoLabel('Lag 1')}, Yield ${infoLabel('Lag 4')}, rolling 4-quarter mean</li><li><b>Historical agricultural:</b> Area Harvested Lag 4, Production Lag 4</li><li><b>Agroclimatic:</b> Rainfall, temperature, relative humidity, and wind speed at Lag 1 and Lag 4</li></ul><p class="muted">Satellite NDVI/EVI, PSA farmgate prices, and integrated PAGASA agri-weather and climate-risk information are maintained as separate contextual layers; they are not part of the active predictor set.</p>`,'activeFeatureGroupsCard')}</div>${satelliteDecision}${card(title('◉','Spatial Representation')+`<p>NASA POWER weather variables use the nearest grid point to a representative provincial centroid. Satellite NDVI/EVI values are quality-screened MODIS observations summarized over cropland classes within provincial boundaries. Both are provincial-scale representations and should not be interpreted as field-level measurements.</p>`)}${card(title('⚠',`Avoiding ${infoLabel('Data Leakage')}`)+`<p><b>The active model does not use target-quarter actual yield, production, harvested area, complete target-quarter weather, or target-quarter satellite vegetation.</b> Only information available before the target period is considered in model feature assessment.</p>`,'leak')}`}
function about(){return hero('ABOUT ANI','Provincial Palay Yield Estimates for Agricultural Insight','ANI provides provincial quarterly palay-yield estimates from historical agricultural records and lagged agroclimatic information. Future periods are Prospective Forecasts, in-progress periods are Current-Quarter Estimates, and completed periods are Retrospective Estimates.',true)+`<div class="twoCol">${card(title('ⓘ','ANI Model Results')+'<p>The XGBoost model estimates quarterly yield in metric tons per hectare using pre-target historical agricultural and agroclimatic inputs. ANI also maintains a cropland-masked MODIS NDVI/EVI layer for vegetation analysis and controlled feature assessment; satellite variables are not inputs to the active deployed model.</p>')}${card(title('▣','Environmental Decision Support')+'<p>ANI presents official agri-weather and climate-risk information, provincial palay market context, and satellite vegetation as separate farmer-facing context. A supplementary water-balance analysis appears only when a current matching outlook is available. None of these contextual outputs alter the XGBoost yield estimate.</p>')}</div>${card(title('🌱','Sustainable Development Alignment')+`<div class="sourceGrid"><div><b>Primary — SDG 2: Zero Hunger</b><p>Supports agricultural productivity assessment and food-production planning.</p></div><div><b>Supporting — SDG 13: Climate Action</b><p>Agroclimatic information provides context; ANI is not a climate-disaster prediction system.</p></div></div>`)}${card(title('⚙','Important Disclaimer')+'<p>ANI model results are machine-learning-based analytical estimates and should not be interpreted as official PSA statistics or guaranteed agricultural outcomes.</p>')}`}
function render(){infoTipCounter=0;const pageChanged=lastRenderedPage!==state.page;let body=state.page==='dashboard'?dashboard():state.page==='forecast'?forecastPage():state.page==='processing'?processing():state.page==='result'?resultPage():state.page==='historical'?historical():state.page==='history'?history():state.page==='model'?model():about();document.getElementById('app').innerHTML=shell(body);const main=document.querySelector('main');if(main)main.classList.toggle('modelDataPage',state.page==='model');bind();if(pageChanged){lastRenderedPage=state.page;requestAnimationFrame(()=>{window.scrollTo({top:0,left:0,behavior:'auto'});document.querySelector('main')?.focus({preventScroll:true})})}}
function toast(t){let e=document.createElement('div');e.className='toast';e.textContent=t;document.body.appendChild(e);setTimeout(()=>e.remove(),2200)}
function positionInfoTip(btn){const popup=btn.closest('.infoTip')?.querySelector('.infoTipPopup');if(!popup)return;const r=btn.getBoundingClientRect(),vw=window.innerWidth,vh=window.innerHeight,panel=btn.closest('.modelCards > div')?.getBoundingClientRect(),w=Math.min(vw<=760?260:280,vw-24,panel?Math.max(120,panel.width-24):280),center=panel?panel.left+panel.width/2:r.left+r.width/2,left=Math.max(12,Math.min(center-w/2,vw-w-12));popup.style.setProperty('--tip-left',left+'px');popup.style.width=w+'px';popup.style.maxWidth=w+'px';popup.classList.remove('tipAbove');const h=popup.offsetHeight||80,below=r.bottom+8,above=r.top-h-8,useAbove=below+h>vh-12&&above>=12,top=useAbove?above:below;popup.classList.toggle('tipAbove',useAbove);popup.style.setProperty('--tip-top',Math.max(12,top)+'px');popup.style.setProperty('--tip-arrow-x',Math.max(14,Math.min(w-14,r.left+r.width/2-left))+'px');popup.classList.add('isPositioned')}
// Fixed-position help follows its trigger when the viewport or scroll position changes.
function repositionInfoTips(){document.querySelectorAll('.infoTipPopup.isPositioned').forEach(popup=>{const wrap=popup.closest('.infoTip'),btn=wrap?.querySelector('.infoTipTrigger');if(!btn)return;const r=btn.getBoundingClientRect();if(r.bottom<0||r.top>window.innerHeight||r.right<0||r.left>window.innerWidth){popup.classList.remove('isPositioned');wrap.classList.remove('isOpen');btn.setAttribute('aria-expanded','false')}else positionInfoTip(btn)})}
window.addEventListener('resize',repositionInfoTips);
window.addEventListener('scroll',repositionInfoTips,{capture:true,passive:true});
function bind(){
  bindSidebar();
  document.querySelectorAll('.infoTipTrigger').forEach(btn=>{const place=()=>positionInfoTip(btn);btn.closest('.infoTip').addEventListener('mouseenter',place);btn.addEventListener('mouseenter',place);btn.addEventListener('focus',place);btn.addEventListener('click',e=>{e.stopPropagation();place();const wrap=btn.closest('.infoTip'),opening=!wrap.classList.contains('isOpen');document.querySelectorAll('.infoTip.isOpen').forEach(x=>{x.classList.remove('isOpen');x.querySelector('.infoTipTrigger')?.setAttribute('aria-expanded','false')});if(opening){wrap.classList.add('isOpen');btn.setAttribute('aria-expanded','true')}});btn.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();btn.closest('.infoTip')?.classList.remove('isOpen');btn.setAttribute('aria-expanded','false');btn.blur()}})});document.querySelector('main')?.addEventListener('click',()=>document.querySelectorAll('.infoTip.isOpen').forEach(x=>{x.classList.remove('isOpen');x.querySelector('.infoTipTrigger')?.setAttribute('aria-expanded','false')}));
  document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{state.page=b.dataset.page;sidebarOpen=false;render()});
  if(state.page==='forecast'){
    refreshForecastAvailability();
    const retryAvailability=document.getElementById('retryAvailability');
    if(retryAvailability)retryAvailability.onclick=()=>refreshForecastAvailability(true);
    document.getElementById('province').onchange=e=>{state.request.province=e.target.value;state.nearestTargetAssessment=null;state.targetSelectionManual=false;state.availableTargets=[];state.availabilityKey=null;state.availabilityFetchedAt=0;state.forecastError='';render()};
    document.getElementById('ecosystem').onchange=e=>{state.request.ecosystem=e.target.value;state.nearestTargetAssessment=null;state.targetSelectionManual=false;state.availableTargets=[];state.availabilityKey=null;state.availabilityFetchedAt=0;state.forecastError='';render()};
    document.getElementById('targetYear').onchange=e=>{state.request.targetYear=+e.target.value;state.targetSelectionManual=true;const first=state.availableTargets.find(t=>t.year===state.request.targetYear);state.request.targetQuarter=first?.quarter??null;render()};
    document.getElementById('targetQuarter').onchange=e=>{state.request.targetQuarter=+e.target.value;state.targetSelectionManual=true;render()};
    document.getElementById('reset').onclick=()=>{state.request={province:'Abra',ecosystem:'Irrigated',targetYear:apiMeta?.suggested_next_target?.year,targetQuarter:apiMeta?.suggested_next_target?.quarter};state.nearestTargetAssessment=null;state.targetSelectionManual=false;state.availableTargets=[];state.availabilityKey=null;state.availabilityFetchedAt=0;state.forecastError='';render()};
    document.getElementById('generate').onclick=()=>{
      const targetExists=state.availableTargets.some(t=>t.year===state.request.targetYear&&t.quarter===state.request.targetQuarter);
      if(!targetExists){state.forecastError='That period is no longer available. Refreshing available periods…';state.availabilityKey=null;render();refreshForecastAvailability(true);return}
      state.forecastError='';state.page='processing';state.processingStep=1;render();let step=1;
      const tm=setInterval(()=>{step++;state.processingStep=step;if(step>6){clearInterval(tm);forecast(state.request).then(f=>{state.current=f;save(state.current);state.page='result';render()}).catch(err=>{state.page='forecast';state.forecastError=err.message;state.availabilityKey=null;render()})}else render()},500)
    };
  }
  if(state.page==='result'){document.getElementById('print').onclick=()=>window.print()}
  if(state.page==='historical'){
    document.getElementById('filterProvince').onchange=e=>{state.filterProvince=e.target.value;state.historicalPage=0;render()};
    document.getElementById('filterEco').onchange=e=>{state.filterEco=e.target.value;state.historicalPage=0;render()};
    document.getElementById('filterYear').onchange=e=>{state.filterYear=e.target.value;state.historicalPage=0;render()};
    document.getElementById('query').oninput=e=>{state.query=e.target.value;state.historicalPage=0;render()};
    document.getElementById('resetFilters').onclick=()=>{state.filterProvince='All Provinces';state.filterEco='All Ecosystems';state.filterYear='All Years';state.query='';state.historicalPage=0;render()};
    document.getElementById('firstPage').onclick=()=>{state.historicalPage=0;render()};
    document.getElementById('previousPage').onclick=()=>{if(state.historicalPage>0){state.historicalPage--;render()}};
    document.getElementById('nextPage').onclick=()=>{state.historicalPage++;render()};
    document.getElementById('lastPage').onclick=()=>{const filteredCount=data.filter(r=>(state.filterProvince==='All Provinces'||r.province===state.filterProvince)&&(state.filterEco==='All Ecosystems'||r.ecosystem===state.filterEco)&&(state.filterYear==='All Years'||r.year==state.filterYear)&&r.province.toLowerCase().includes(state.query.toLowerCase())).length;state.historicalPage=Math.max(0,Math.ceil(filteredCount/10)-1);render()}
  }
  if(state.page==='history'){
    document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{if(confirm('Delete this model result?'))removeForecast(b.dataset.delete)});
    document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{state.current=saved().find(x=>x.forecastId===b.dataset.view);state.page='result';render()});
    const c=document.getElementById('clearAll');
    if(c)c.onclick=()=>{if(confirm('Clear all saved model results?')){localStorage.removeItem('ani-saved-forecasts');window.dispatchEvent(new CustomEvent('ani:forecasts-updated'));render()}}
  }
}
window.addEventListener('ani:forecasts-updated',()=>{if(state.page==='dashboard'||state.page==='history')render()});window.addEventListener('storage',e=>{if(e.key==='ani-saved-forecasts'&&(state.page==='dashboard'||state.page==='history'))render()});loadEnvironmentalDecisionSupport();loadRealData().then(()=>{const next=apiMeta?.suggested_next_target;if(next){state.request.targetYear=next.year;state.request.targetQuarter=next.quarter;}render();}).catch(err=>{console.error('ANI startup failed:',err);document.getElementById('app').innerHTML='<main class="serviceError"><h1>ANI Service Unavailable</h1><p>The ANI data service could not be reached. Please try again or contact the system administrator if the problem continues.</p></main>';});
